9d69;margin-right:6px}.hero-stat{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:26px 0}.hero-stat strong{display:block;font-size:32px;letter-spacing:-.05em}.hero-stat small{color:var(--muted)}.donut{width:105px;height:105px;border-radius:50%;background:conic-gradient(var(--green2) 0 70%,#e5b94f 70% 100%);display:grid;place-items:center;flex-shrink:0}.donut:after{content:"";position:absolute;width:72px;height:72px;background:#f8f9f3;border-radius:50%}.donut span{position:relative;z-index:1;font-size:12px;font-weight:900}.card-foot{font-size:10px;color:var(--muted);border-top:1px solid var(--line);padding-top:13px}.wrap{max-width:1280px;margin:auto;padding:35px clamp(18px,4.5vw,60px) 60px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px}.section-head h2{font-size:26px;letter-spacing:-.045em;margin:0 0 7px}.section-head p{font-size:13px;color:var(--muted);margin:0}.controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.btn-refresh{background:var(--green);color:white}.last-update{font-size:11px;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metric,.panel{background:var(--white);border:1px solid var(--line);border-radius:18px;padding:22px;box-shadow:0 4px 15px #193d2605;min-width:0}.metric-label{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;gap:8px;align-items:center}.metric-icon{background:var(--mint);color:var(--green2);border-radius:11px;width:34px;height:34px;display:grid;place-items:center;font-size:17px}.metric-value{font-size:clamp(22px,2.4vw,31px);font-weight:900;letter-spacing:-.055em;margin:18px 0 6px;overflow-wrap:anywhere}.metric-note{font-size:11px;color:var(--muted);line-height:1.5}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:16px;margin-top:17px}.panel h3{font-size:17px;margin:0 0 6px;letter-spacing:-.03em}.sub{font-size:12px;color:var(--muted);line-height:1.55;margin:0 0 20px}.tag{display:inline-block;padding:7px 9px;border-radius:8px;background:var(--mint);color:var(--green2);font-size:10px;font-weight:850}.panel-heading{display:flex;justify-content:space-between;gap:10px;align-items:start}.candidate-list{display:grid;gap:17px}.candidate{display:grid;grid-template-columns:38px 1fr auto;gap:11px;align-items:center}.avatar{width:38px;height:38px;border-radius:12px;background:var(--mint);color:var(--green2);font-size:12px;font-weight:900;display:grid;place-items:center}.candidate-name{font-size:13px;font-weight:850;overflow-wrap:anywhere}.candidate-detail{font-size:11px;color:var(--muted);margin-top:4px}.candidate-value{text-align:right;font-size:13px;font-weight:850}.candidate-value small{display:block;color:var(--muted);font-size:11px;font-weight:500;margin-top:4px}.track{height:8px;background:#edf0eb;border-radius:99px;overflow:hidden;margin-top:10px}.fill{height:100%;width:0;background:var(--green2);border-radius:99px;transition:width .5s}.fill.alt{background:var(--gold)}.empty{border:1px dashed #d4ddd4;background:#fafbf8;padding:22px;border-radius:14px;color:var(--muted);font-size:13px;line-height:1.6}.participation{display:grid;grid-template-columns:140px 1fr;gap:22px;align-items:center}.ring{width:136px;height:136px;border-radius:50%;background:conic-gradient(var(--green2) 0 0%,var(--gold) 0 100%);display:grid;place-items:center;position:relative}.ring:before{content:"";position:absolute;width:96px;height:96px;border-radius:50%;background:white}.ring-center{z-index:1;text-align:center}.ring-center strong{display:block;font-size:23px;letter-spacing:-.05em}.ring-center span{font-size:10px;color:var(--muted)}.legend{display:grid;gap:13px}.legend-row{display:grid;grid-template-columns:9px 1fr auto;gap:9px;align-items:center;font-size:12px}.dot{width:9px;height:9px;border-radius:3px;background:var(--green2)}.legend-row span:nth-child(2){color:var(--muted)}.legend-row strong{font-size:12px}.source{display:flex;align-items:center;justify-content:space-between;gap:18px;background:#e7eee5;padding:20px 22px;border-radius:16px;margin-top:17px}.source h4{font-size:13px;margin:0 0 5px}.source p{font-size:11px;color:#65756a;line-height:1.5;margin:0}.source a{font-size:12px;font-weight:850;color:var(--green2);white-space:nowrap}.notice{font-size:11px;color:var(--muted);line-height:1.6;margin:15px 2px}.footer{background:#102f28;color:#c7d8ce;padding:24px clamp(20px,5vw,76px);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;font-size:11px}.footer strong{color:white}.footer a{color:var(--gold)}.error{background:#fff0ed;color:#8b3529;border:1px solid #f0c8c1;border-radius:12px;padding:13px 15px;margin-bottom:16px;font-size:12px;line-height:1.5}.hidden{display:none!important}
@media(max-width:900px){.hero{grid-template-columns:1fr}.hero-card{max-width:450px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}.nav{display:none}}@media(max-width:560px){.topbar{padding-top:13px;padding-bottom:13px}.status-pill{display:none}.hero{padding-top:42px;padding-bottom:45px}.hero-card{transform:none}.section-head{align-items:start;flex-direction:column}.metric{padding:15px}.metric-value{font-size:22px}.metric-label{font-size:10px}.metric-icon{width:29px;height:29px}.panel{padding:17px}.participation{grid-template-columns:1fr;justify-items:center}.legend{width:100%}.source{align-items:flex-start;flex-direction:column}.candidate{grid-template-columns:34px minmax(0,1fr) auto;gap:8px}.avatar{width:34px;height:34px}.candidate-value{font-size:11px}}
