<section class="hero"><div><div class="eyebrow">Democracia em números</div><h1>Entenda o voto.<br><span>Enxergue os dados.</span></h1><p>Um painel para explorar estatísticas eleitorais do Brasil. Os indicadores são solicitados ao seu endpoint PHP, que consulta os dados públicos do Tribunal Superior Eleitoral.</p><div class="hero-actions"><a class="btn btn-gold" href="#painel">Explorar estatísticas ↘</a><a class="btn btn-outline" href="#fontes">Conheça as fontes</a></div></div><div class="hero-card"><div class="card-top"><span>Painel eleitoral</span><span><i class="live-dot"></i><span id="liveState">Conectando</span></span></div><div class="hero-stat"><div><small>Votos válidos informados pela API</small><strong id="heroValid">—</strong><small id="heroElection">Aguardando dados do TSE</small></div><div class="donut"><span id="heroDonut">API</span></div></div><div class="card-foot">Atualização automática a cada 60 segundos · Sem dados inventados</div></div></section>
<main class="wrap" id="painel"><div id="errorBox" class="error hidden" role="status"></div><div class="section-head"><div><h2>O Brasil nas urnas</h2><p>Indicadores recebidos pelo endpoint PHP conectado ao TSE.</p></div><div class="controls"><span class="last-update" id="lastUpdate">Ainda não atualizado</span><button class="btn btn-refresh" id="refreshBtn">↻ Atualizar agora</button></div></div>
<div class="metrics"><article class="metric"><div class="metric-label"><span>Comparecimento</span><span class="metric-icon">↗</span></div><div class="metric-value" id="turnout">—</div><div class="metric-note" id="turnoutNote">Aguardando resposta da API</div></article><article class="metric"><div class="metric-label"><span>Abstenções</span><span class="metric-icon">◷</span></div><div class="metric-value" id="absence">—</div><div class="metric-note">Eleitores que não compareceram</div></article><article class="metric"><div class="metric-label"><span>Votos válidos</span><span class="metric-icon">✓</span></div><div class="metric-value" id="valid">—</div><div class="metric-note">Total retornado pela API</div></article><article class="metric"><div class="metric-label"><span>Votos brancos e nulos</span><span class="metric-icon">◌</span></div><div class="metric-value" id="blankNull">—</div><div class="metric-note" id="blankNullNote">Valores recebidos do TSE</div></article></div>
<div class="grid"><section class="panel" id="candidatos"><div class="panel-heading"><div><h3>Resultados disponíveis</h3><p class="sub" id="candidateSubtitle">Os candidatos serão listados conforme os dados recebidos da API.</p></div><span class="tag">DADOS DA API</span></div><div id="candidateList" class="candidate-list"><div class="empty">Conectando ao endpoint <strong>resultado-presidente.php</strong>…</div></div></section><section class="panel" id="participacao"><div class="panel-heading"><div><h3>Participação eleitoral</h3><p class="sub">Resumo dos dados de comparecimento e abstenção recebidos.</p></div></div><div class="participation"><div class="ring" id="ring"><div class="ring-center"><strong id="ringValue">—</strong><span>comparecimento</span></div></div><div class="legend"><div class="legend-row"><i class="dot"></i><span>Comparecimento</span><strong id="legendTurnout">—</strong></div><div class="legend-row"><i class="dot" style="background:var(--gold)"></i><span>Abstenção</span><strong id="legendAbsence">—</strong></div><div class="legend-row"><i class="dot" style="background:var(--blue)"></i><span>Votos brancos</span><strong id="legendBlank">—</strong></div><div class="legend-row"><i class="dot" style="background:var(--red)"></i><span>Votos nulos</span><strong id="legendNull">—</strong></div></div></div></section></div>
<section class="source" id="fontes"><div><h4>Fonte dos dados</h4><p id="sourceText">Os indicadores serão carregados do endpoint local, que consulta os dados públicos do TSE.</p></div><a href="https://www.tse.jus.br/" target="_blank" rel="noreferrer">Acessar o TSE ↗</a></section><p class="notice">Transparência: esta página não preenche estatísticas com números de exemplo. Se o endpoint não retornar um indicador, ele ficará como “—”. A atualização automática depende de o arquivo resultado-presidente.php estar funcionando e de a fonte do TSE estar acessível.</p></main>
<footer class="footer"><div><strong>voto.em dados</strong> — informação pública para todo mundo.</div><div>Fonte oficial: <a href="https://www.tse.jus.br/" target="_blank" rel="noreferrer">Tribunal Superior Eleitoral</a></div></footer>
<script>
const API_URL = <?php echo json_encode($apiUrl, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); ?>;
const $ = id => document.getElementById(id);
const fmt = new Intl.NumberFormat('pt-BR');
function rawNumber(value){
  if(value === null || value === undefined || value === '') return null;
  if(typeof value === 'number') return value;
  const s = String(value).trim().replace(/%/g,'').replace(/\s/g,'');
  if(/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) return Number(s.replace(/\./g,'').replace(',','.'));
  if(/^\d+(,\d+)?$/.test(s)) return Number(s.replace(',','.'));
  const n = Number(s.replace(/,/g,''));
  return Number.isFinite(n) ? n : null;
}
function showNum(value){const n=rawNumber(value);return n===null?'—':fmt.format(n)}
function showPercent(value){if(value===null||value===undefined||value==='')return '—';let n=rawNumber(value);if(n===null)return String(value);if(n>0&&n<=1)n*=100;return n.toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'}
function first(obj, keys){for(const k of keys){if(obj && obj[k]!==undefined && obj[k]!==null && obj[k]!=='')return obj[k]}return null}
function deepFind(obj, keys, depth=0){if(!obj||typeof obj!=='object'||depth>5)return null;const direct=first(obj,keys);if(direct!==null)return direct;for(const val of Object.values(obj)){if(val&&typeof val==='object'){const found=deepFind(val,keys,depth+1);if(found!==null)return found}}return null}
function candidateName(c){return first(c,['nm','nmu','nome','name','cand','n']) || 'Candidato'}
function candidateVotes(c){return first(c,['vap','votos','votos_validos','tv','v'])}
function candidatePercent(c){return first(c,['pvap','percentual','porcentagem','percent','p'])}
function candidatesFrom(data){let arr=data?.candidatos;if(Array.isArray(arr))return arr;const found=deepFind(data,['agr','candidatos']);return Array.isArray(found)?found:[]}
function setText(id,value){$(id).textContent=value===null||value===undefined||value===''?'—':String(value)}
function renderCandidates(list){const root=$('candidateList');root.innerHTML='';if(!list.length){root.innerHTML='<div class="empty">A API respondeu, mas não trouxe uma lista de candidatos reconhecível. Os cartões acima ainda exibem os indicadores que estiverem disponíveis. Podemos ajustar o mapeamento quando conferirmos o JSON retornado.</div>';return}
 const totalVotes=list.reduce((sum,c)=>sum+(rawNumber(candidateVotes(c))||0),0);
 list.slice(0,12).forEach((c,i)=>{const name=candidateName(c);const votes=candidateVotes(c);let pct=candidatePercent(c);if(pct===null&&totalVotes>0&&rawNumber(votes)!==null)pct=(rawNumber(votes)/totalVotes)*100;const percentText=pct===null?'—':showPercent(pct);const width=Math.max(0,Math.min(100,rawNumber(pct)||0));const row=document.createElement('div');row.className='candidate';const initials=name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();row.innerHTML=`<div class="avatar">${initials.replace(/[&<>"']/g,'')}</div><div><div class="candidate-name"></div><div class="candidate-detail">${votes!==null?'Votos recebidos':'Informação de votação não disponível'}</div><div class="track"><div class="fill ${i%2?'alt':''}" style="width:${width}%"></div></div></div><div class="candidate-value"><span>${votes!==null?showNum(votes):'—'}</span><small>${percentText}</small></div>`;row.querySelector('.candidate-name').textContent=name;root.appendChild(row)})}
async function updateDashboard(){const btn=$('refreshBtn');btn.disabled=true;btn.textContent='↻ Consultando…';$('liveState').textContent='Consultando';$('errorBox').classList.add('hidden');try{const response=await fetch(API_URL+'?t='+Date.now(),{cache:'no-store',headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('O endpoint respondeu com HTTP '+response.status+'.');const data=await response.json();if(data.status==='erro')throw new Error(data.mensagem||'O endpoint retornou um erro.');
 const turnout=first(data,['comparecimento_percentual','percentual_comparecimento','turnout_percent','comparecimento','turnout']);const absence=first(data,['abstencoes','abstencao','absence']);const valid=first(data,['votos_validos','validos','valid']);const blank=first(data,['votos_brancos','brancos','blank']);const nul=first(data,['votos_nulos','nulos','null_votes']);const election=first(data,['eleicao','nome_eleicao','pleito']);const updated=first(data,['data_atualizacao','atualizacao','dg','dh']);
 const turnoutNumber=rawNumber(turnout), absenceNumber=rawNumber(absence);let turnoutPct=null; if(turnoutNumber!==null){if(turnoutNumber<=100)turnoutPct=turnoutNumber>1?turnoutNumber:turnoutNumber*100;else if(absenceNumber!==null&&turnoutNumber+absenceNumber>0)turnoutPct=turnoutNumber/(turnoutNumber+absenceNumber)*100;}let absencePct=turnoutPct===null?null:100-turnoutPct;
 setText('turnout',turnoutNumber===null?'—':(turnoutNumber>100?showNum(turnoutNumber):showPercent(turnout)));setText('absence',showNum(absence));setText('valid',showNum(valid));setText('blankNull',(blank!==null||nul!==null)?`${blank!==null?showNum(blank):'—'} / ${nul!==null?showNum(nul):'—'}`:'—');setText('turnoutNote',turnoutNumber===null?'Valor não informado pela API':(turnoutNumber>100?'Eleitores que compareceram':'Percentual de comparecimento'));setText('blankNullNote','Brancos / nulos');setText('heroValid',showNum(valid));setText('heroElection',election||'Dados retornados pelo endpoint');setText('heroDonut',turnoutPct===null?'TSE':showPercent(turnoutPct));setText('ringValue',turnoutPct===null?'—':showPercent(turnoutPct));setText('legendTurnout',turnoutPct===null?'—':showPercent(turnoutPct));setText('legendAbsence',absencePct===null?'—':showPercent(absencePct));setText('legendBlank',showNum(blank));setText('legendNull',showNum(nul));setText('candidateSubtitle',election?String(election):'Candidatos listados conforme a resposta da API');
 if(turnoutPct!==null){const normalized=Math.max(0,Math.min(100,turnoutPct));$('ring').style.background=`conic-gradient(var(--green2) 0 ${normalized}%,var(--gold) ${normalized}% 100%)`}
 renderCandidates(candidatesFrom(data));$('sourceText').textContent='Resposta recebida do endpoint local resultado-presidente.php. Fonte configurada no endpoint: Tribunal Superior Eleitoral (TSE).';$('liveState').textContent='Conectado';$('lastUpdate').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+(updated?' · fonte: '+updated:'');
 }catch(err){$('liveState').textContent='Sem conexão';$('errorBox').textContent='Não foi possível atualizar os dados: '+err.message+' Confira se resultado-presidente.php abre e retorna JSON válido.';$('errorBox').classList.remove('hidden');$('candidateList').innerHTML='<div class="empty">Os dados não puderam ser carregados agora. Confira se o XAMPP está ligado e se o arquivo <strong>resultado-presidente.php</strong> está na mesma pasta que esta página.</div>';$('lastUpdate').textContent='Falha na atualização';}finally{btn.disabled=false;btn.textContent='↻ Atualizar agora'}}
$('refreshBtn').addEventListener('click',updateDashboard);updateDashboard();setInterval(updateDashboard,60000);
</script>
</body>
